// Compose the Resend payload. apps/n8n/scripts/import.sh replaces the EMAIL_FROM_JSON / LEAD_TO_JSON placeholders below
// with complete JS string literals (JSON-encoded .env values, quotes included), so a sender such as
// Cincinnati Hotel's "Front Desk" <desk@...> cannot break this code.
const FROM = String(${EMAIL_FROM_JSON}).trim();
const TO = String(${LEAD_TO_JSON}).split(',').map((s) => s.trim()).filter(Boolean);
if (TO.length === 0) throw new Error('LEAD_TO is not configured');
if (!FROM) throw new Error('EMAIL_FROM is not configured');

const body = $('Webhook').first().json.body || {};
const lead = body.lead || {};
const transcript = Array.isArray(body.transcript) ? body.transcript : [];
const unanswered = body.unanswered_question || null;

const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const nl2br = (v) => esc(v).replace(/\r?\n/g, '<br>');

// "Summarize" runs with On Error: Continue, so its item may carry no text.
const raw = $input.first() ? $input.first().json : {};
const summary = typeof raw.text === 'string' && raw.text.trim() ? raw.text.trim() : null;

const name = String(lead.name || 'unknown guest').replace(/[\r\n]+/g, ' ').trim();
const subject = 'Cincinnati Hotel chatbot — contact request from ' + name;
const who = (m) => (m.role === 'assistant' ? 'Assistant' : 'Guest');

// The body shows only the latest messages so a long chat never passes Gmail's ~102 KB clipping limit;
// the full conversation goes in the attached Markdown file.
const TAIL = 6;
const MAX_INLINE = 1000;
const clip = (v) => { const s = String(v || ''); return s.length > MAX_INLINE ? s.slice(0, MAX_INLINE).trimEnd() + '…' : s; };
const tail = transcript.slice(-TAIL);
const filename = 'transcript-' + (String(body.session_id || '').replace(/[^0-9a-zA-Z]/g, '').slice(0, 8) || 'chat') + '.md';
const note = transcript.length
  ? 'Showing the last ' + tail.length + ' of ' + transcript.length + ' messages. The full conversation is attached (' + filename + ').'
  : 'The conversation is empty.';

const lines = tail.map((m) => '[' + (m.created_at || '') + '] ' + who(m) + ': ' + clip(m.content));

const textParts = [
  'Contact request from the Cincinnati Hotel chatbot',
  '',
  'Name: ' + (lead.name || ''),
  'Phone: ' + (lead.phone || ''),
  'Email: ' + (lead.email || ''),
  'Session: ' + (body.session_id || ''),
  '',
];
if (unanswered) textParts.push('Unanswered question: ' + unanswered, '');
textParts.push(summary ? summary : '(Automatic summary unavailable — see the attached transcript.)', '', 'LATEST MESSAGES', note, '', lines.join('\n') || '(empty)');
const text = textParts.join('\n');

const rows = [['Name', lead.name], ['Phone', lead.phone], ['Email', lead.email], ['Session', body.session_id]]
  .map(([k, v]) => '<tr><td style="padding:4px 12px 4px 0;color:#555"><b>' + k + '</b></td><td style="padding:4px 0">' + esc(v) + '</td></tr>')
  .join('');
const htmlLines = tail.map((m) => '<p style="margin:6px 0"><b>' + who(m) + '</b> <span style="color:#888;font-size:12px">' + esc(m.created_at || '') + '</span><br>' + nl2br(clip(m.content)) + '</p>').join('') || '<p>(empty)</p>';

const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:640px">'
  + '<h2 style="margin:0 0 12px">Contact request</h2>'
  + '<table style="border-collapse:collapse">' + rows + '</table>'
  + (unanswered ? '<div style="margin:16px 0;padding:10px 12px;background:#fff4e5;border-left:4px solid #f59e0b"><b>Unanswered question:</b><br>' + nl2br(unanswered) + '</div>' : '')
  + '<h3 style="margin:16px 0 6px">Summary</h3>'
  + (summary ? '<p>' + nl2br(summary) + '</p>' : '<p><i>Automatic summary unavailable — see the attached transcript.</i></p>')
  + '<h3 style="margin:16px 0 6px">Latest messages</h3>'
  + '<p style="color:#555;font-size:12px">' + esc(note) + '</p>' + htmlLines
  + '</div>';

// Full transcript, untruncated. No phone / email here: they are in the email header and reply_to.
const md = [
  '# Cincinnati Hotel chatbot — conversation transcript',
  '',
  '- Session: ' + (body.session_id || ''),
  '- Guest: ' + name,
  '- Exported: ' + new Date().toISOString(),
  '- Messages: ' + transcript.length,
  '',
  ...(unanswered ? ['## Unanswered question', '', String(unanswered), ''] : []),
  '## Summary',
  '',
  summary || '_Automatic summary unavailable._',
  '',
  '## Conversation',
  '',
  ...(transcript.length
    ? transcript.flatMap((m) => ['### ' + who(m) + ' — ' + (m.created_at || ''), '', String(m.content || ''), '', '---', ''])
    : ['_(empty)_', '']),
].join('\n');

// UTF-8 → base64. Buffer exists in the n8n Code node; the fallback keeps the email working if a sandbox hides it.
const toBase64 = (s) => {
  if (typeof Buffer !== 'undefined') return Buffer.from(s, 'utf8').toString('base64');
  const bytes = new TextEncoder().encode(s);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(bin);
};

const payload = {
  from: FROM.trim(),
  to: TO,
  subject,
  html,
  text,
  attachments: [{ filename, content: toBase64(md), content_type: 'text/markdown; charset=utf-8' }],
};
if (lead.email) payload.reply_to = lead.email;

return [{ json: { payload, summary } }];
